package com.eduflow.backend;
import com.eduflow.backend.entity.*;
import com.eduflow.backend.repository.*;
import com.eduflow.backend.security.JwtService;
import com.fasterxml.jackson.databind.*;
import jakarta.persistence.EntityManager;
import java.time.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.annotation.DirtiesContext;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.MediaType;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.request.*;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:parent-tests;MODE=MySQL;DB_CLOSE_DELAY=-1","app.exams.expiry-enabled=false"})
@AutoConfigureMockMvc @Transactional @DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
class ParentPortalTests {
 @Autowired MockMvc mvc;@Autowired ObjectMapper mapper;@Autowired JwtService jwt;@Autowired EntityManager em;@Autowired PasswordEncoder encoder;
 @Autowired UserRepository users;@Autowired StudentRepository students;@Autowired ParentProfileRepository profiles;@Autowired ParentStudentLinkRepository links;
 User adminUser,parentUser,parent2User;String admin,parent,parent2,teacher,studentToken;ParentProfile profile,profile2;Student student,other;Course course;Batch batch;BatchEnrollment enrollment;
 LocalDate today;Instant now;
 <T>T persist(T entity){em.persist(entity);em.flush();return entity;}
 String token(String email,Role role){return jwt.generateToken(users.saveAndFlush(new User(email,email+"@parent.test","unused",role)).getEmail());}
 @BeforeEach void setup(){today=LocalDate.now(ZoneId.of("Asia/Kolkata"));now=Instant.now();
  adminUser=users.saveAndFlush(new User("Admin","admin@parent.test","unused",Role.ADMIN));admin=jwt.generateToken(adminUser.getEmail());
  parentUser=users.saveAndFlush(new User("Parent One","one@parent.test","unused",Role.PARENT));parent=jwt.generateToken(parentUser.getEmail());
  parent2User=users.saveAndFlush(new User("Parent Two","two@parent.test","unused",Role.PARENT));parent2=jwt.generateToken(parent2User.getEmail());teacher=token("teacher",Role.TEACHER);studentToken=token("student",Role.STUDENT);
  profile=new ParentProfile();profile.setUser(parentUser);profile.setPhoneNumber("9876543210");persist(profile);profile2=new ParentProfile();profile2.setUser(parent2User);profile2.setPhoneNumber("9876543211");persist(profile2);
  course=new Course();course.setCode("PARENT");course.setName("Mathematics");course.setDurationWeeks(12);persist(course);
  batch=new Batch();batch.setCourse(course);batch.setCode("PARENT");batch.setName("Evening");batch.setCapacity(10);batch.setStartDate(today.minusDays(20));batch.setEndDate(today.plusMonths(2));batch.setStatus(BatchStatus.ACTIVE);persist(batch);
  student=makeStudent("PARENT-1");other=makeStudent("PARENT-2");enrollment=new BatchEnrollment();enrollment.setBatch(batch);enrollment.setStudent(student);enrollment.setEnrollmentDate(today.minusDays(10));persist(enrollment);
 }
 Student makeStudent(String code){var s=new Student(code);s.setFullName(code);s.setEmail(code+"@admission.test");s.setPhone("9876543210");s.setDateOfBirth(today.minusYears(18));s.setAdmissionDate(today.minusDays(10));s.setAddress("Address");s.setGuardianName("Guardian");s.setGuardianPhone("9876543211");return persist(s);}
 MockHttpServletRequestBuilder json(MockHttpServletRequestBuilder b,Object data,String token)throws Exception{return b.header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(data));}
 JsonNode body(MvcResult r)throws Exception{return mapper.readTree(r.getResponse().getContentAsString());}
 JsonNode createLink(ParentProfile p,Student s,boolean primary)throws Exception{return body(mvc.perform(json(post("/api/parents/links"),Map.of("parentId",p.getId(),"studentId",s.getId(),"relationshipType","GUARDIAN","primaryGuardian",primary,"reason","Documents checked at institute"),admin)).andExpect(status().isCreated()).andReturn());}
 JsonNode verify(JsonNode link)throws Exception{return body(mvc.perform(json(post("/api/parents/links/"+link.get("id").asLong()+"/verify"),Map.of("version",link.get("version").asLong(),"reason","Identity and guardian consent verified"),admin)).andExpect(status().isOk()).andReturn());}
 void verified()throws Exception{verify(createLink(profile,student,true));}
 String childPath(String suffix){return "/api/parents/children/"+student.getId()+suffix;}
 @Test void adminCreatesParentWithBcryptAndExistingLoginWorks()throws Exception{var input=Map.of("fullName","New Parent","email","new@parent.test","password","Testing@2026","phoneNumber","9876543210");var created=body(mvc.perform(json(post("/api/parents"),input,admin)).andExpect(status().isCreated()).andReturn());assertThat(created.toString()).doesNotContain("password");assertThat(encoder.matches("Testing@2026",users.findByEmail("new@parent.test").orElseThrow().getPassword())).isTrue();mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content(mapper.writeValueAsString(Map.of("email","new@parent.test","password","Testing@2026")))).andExpect(status().isOk()).andExpect(jsonPath("role").value("PARENT"));}
 @Test void duplicateProfilesAndNonParentAccountsAreRejected()throws Exception{mvc.perform(json(post("/api/parents"),Map.of("userId",parentUser.getId(),"phoneNumber","9876543210"),admin)).andExpect(status().isConflict());mvc.perform(json(post("/api/parents"),Map.of("userId",adminUser.getId(),"phoneNumber","9876543210"),admin)).andExpect(status().isBadRequest());for(String token:List.of(parent,teacher,studentToken))mvc.perform(json(post("/api/parents"),Map.of("userId",parentUser.getId(),"phoneNumber","9876543210"),token)).andExpect(status().isForbidden());}
 @Test void pendingRelationshipNeverExposesChildAndVerifiedDoes()throws Exception{var link=createLink(profile,student,true);mvc.perform(get("/api/parents/me/children").header("Authorization","Bearer "+parent)).andExpect(jsonPath("totalElements").value(0));mvc.perform(get(childPath("/dashboard")).header("Authorization","Bearer "+parent)).andExpect(status().isForbidden());var verified=verify(link);assertThat(verified.get("verifiedBy").asText()).isEqualTo("Admin");assertThat(verified.get("verifiedAt").isNull()).isFalse();mvc.perform(get("/api/parents/me/children").header("Authorization","Bearer "+parent)).andExpect(jsonPath("content[0].id").value(student.getId()));mvc.perform(get(childPath("/dashboard")).header("Authorization","Bearer "+parent)).andExpect(status().isOk()).andExpect(jsonPath("child.fullName").value(student.getFullName()));}
 @Test void duplicateActiveLinksAreRejectedAndRevocationIsImmediate()throws Exception{var link=verify(createLink(profile,student,true));mvc.perform(json(post("/api/parents/links"),Map.of("parentId",profile.getId(),"studentId",student.getId(),"relationshipType","FATHER","reason","duplicate"),admin)).andExpect(status().isConflict());mvc.perform(json(post("/api/parents/links/"+link.get("id").asLong()+"/revoke"),Map.of("version",link.get("version").asLong(),"reason","Consent withdrawn"),admin)).andExpect(status().isOk());for(String suffix:List.of("","/dashboard","/attendance","/fees","/results","/assignments","/resources","/progress"))mvc.perform(get(childPath(suffix)).header("Authorization","Bearer "+parent)).andExpect(status().isForbidden());mvc.perform(get("/api/parents/links/"+link.get("id").asLong()+"/history").header("Authorization","Bearer "+admin)).andExpect(jsonPath("totalElements").value(3)).andExpect(jsonPath("content[0].reason").value("Consent withdrawn"));}
 @Test void revokedRelationshipCanReturnToPendingWithoutErasingHistory()throws Exception{var link=verify(createLink(profile,student,false));mvc.perform(json(post("/api/parents/links/"+link.get("id").asLong()+"/revoke"),Map.of("version",link.get("version").asLong(),"reason","Old authorization revoked"),admin)).andExpect(status().isOk());var pending=createLink(profile,student,false);assertThat(pending.get("id")).isEqualTo(link.get("id"));mvc.perform(get(childPath("/fees")).header("Authorization","Bearer "+parent)).andExpect(status().isForbidden());verify(pending);mvc.perform(get("/api/parents/links/"+pending.get("id").asLong()+"/history").header("Authorization","Bearer "+admin)).andExpect(jsonPath("totalElements").value(5));}
 @Test void multipleChildrenAndGuardiansWorkAndPrimaryIsUnique()throws Exception{verified();verify(createLink(profile,other,true));verify(createLink(profile2,student,false));mvc.perform(get("/api/parents/me/children").header("Authorization","Bearer "+parent)).andExpect(jsonPath("totalElements").value(2));mvc.perform(get(childPath("/dashboard")).header("Authorization","Bearer "+parent2)).andExpect(status().isOk());}
 @Test void secondPrimaryGuardianAndUnauthorizedVerificationFail()throws Exception{verified();var link=createLink(profile2,student,true);for(String token:List.of(parent,parent2,teacher,studentToken))mvc.perform(json(post("/api/parents/links/"+link.get("id").asLong()+"/verify"),Map.of("version",0,"reason","Not authorized"),token)).andExpect(status().isForbidden());mvc.perform(json(post("/api/parents/links/"+link.get("id").asLong()+"/verify"),Map.of("version",link.get("version").asLong(),"reason","Checked"),admin)).andExpect(status().isConflict());}
 @Test void unrelatedChildrenAndDirectoryCandidatesAreDenied()throws Exception{verified();for(String suffix:List.of("","/dashboard","/attendance","/fees","/results","/assignments","/resources","/progress"))mvc.perform(get("/api/parents/children/"+other.getId()+suffix).header("Authorization","Bearer "+parent)).andExpect(status().isForbidden());for(String url:List.of("/api/parents","/api/parents/links","/api/parents/candidates/users","/api/students"))mvc.perform(get(url).header("Authorization","Bearer "+parent)).andExpect(status().isForbidden());}
 @Test void inactiveProfileBlocksVerifiedLinks()throws Exception{verified();mvc.perform(json(put("/api/parents/"+profile.getId()),Map.of("version",profile.getVersion(),"fullName","Parent One","phoneNumber","9876543210","status","INACTIVE"),admin)).andExpect(status().isOk());mvc.perform(get(childPath("/fees")).header("Authorization","Bearer "+parent)).andExpect(status().isForbidden());mvc.perform(get("/api/parents/me/children").header("Authorization","Bearer "+parent)).andExpect(jsonPath("totalElements").value(0));}
 @Test void ownProfileUpdateCannotChangeLoginRoleStatusOrLinks()throws Exception{mvc.perform(json(put("/api/parents/me"),Map.of("version",profile.getVersion(),"fullName","Updated Name","phoneNumber","9876543210","email","contact@parent.test","role","ADMIN","status","INACTIVE","userId",adminUser.getId()),parent)).andExpect(status().isOk()).andExpect(jsonPath("loginEmail").value("one@parent.test")).andExpect(jsonPath("email").value("contact@parent.test")).andExpect(jsonPath("status").value("ACTIVE"));assertThat(parentUser.getRole()).isEqualTo(Role.PARENT);assertThat(parentUser.getFullName()).isEqualTo("Updated Name");assertThat(links.count()).isZero();}
 @Test void noChildrenAndNoDataAreExplicit()throws Exception{mvc.perform(get("/api/parents/dashboard").header("Authorization","Bearer "+parent)).andExpect(status().isOk()).andExpect(jsonPath("linked").value(false));verified();mvc.perform(get(childPath("/progress")).header("Authorization","Bearer "+parent)).andExpect(status().isOk()).andExpect(jsonPath("attendance.attendancePercentage").isEmpty()).andExpect(jsonPath("averageExamPercentage").isEmpty()).andExpect(jsonPath("assignmentCompletionPercentage").isEmpty());}
 void attendance(AttendanceStatus status,boolean finalized,int day){var session=new AttendanceSession();session.setBatch(batch);session.setSessionDate(today.minusDays(day));session.setOccurrenceKey("MANUAL-"+day+"-"+status);session.setMarkedBy(adminUser);session.setStatus(finalized?AttendanceSessionStatus.FINALIZED:AttendanceSessionStatus.DRAFT);persist(session);var record=new AttendanceRecord();record.setSession(session);record.setStudent(student);record.setStatus(status);persist(record);}
 @Test void attendanceUsesExistingFormulaAndRetainsWithdrawalHistory()throws Exception{verified();attendance(AttendanceStatus.PRESENT,true,1);attendance(AttendanceStatus.LATE,true,2);attendance(AttendanceStatus.ABSENT,true,3);attendance(AttendanceStatus.EXCUSED,true,4);attendance(AttendanceStatus.ABSENT,false,5);enrollment.setStatus(EnrollmentStatus.WITHDRAWN);enrollment.setWithdrawalDate(today);em.flush();mvc.perform(get(childPath("/attendance")).header("Authorization","Bearer "+parent)).andExpect(status().isOk()).andExpect(jsonPath("totals.attendancePercentage").value(66.67)).andExpect(jsonPath("totals.totalEligibleFinalizedSessions").value(4)).andExpect(jsonPath("history.totalElements").value(4));}
 StudentFeeAccount feeAccount(Student s){var n=s==student?enrollment:new BatchEnrollment();if(s!=student){n.setStudent(s);n.setBatch(batch);n.setEnrollmentDate(today.minusDays(5));persist(n);}var f=new StudentFeeAccount();f.setStudent(s);f.setEnrollment(n);f.setStructureName("Agreed tuition");f.setAgreementDate(today.minusDays(5));f.setTuitionFee(new BigDecimal("1000.00"));f.setAdmissionFee(BigDecimal.ZERO);f.setMaterialFee(BigDecimal.ZERO);f.setOtherFee(BigDecimal.ZERO);f.setOriginalAmount(new BigDecimal("1000.00"));f.setDiscountAmount(BigDecimal.ZERO);f.setFinalPayableAmount(new BigDecimal("1000.00"));persist(f);return f;}
 FeePayment payment(StudentFeeAccount account,FeePaymentStatus status){var p=new FeePayment();p.setFeeAccount(account);p.setAmount(new BigDecimal("200.00"));p.setPaymentDate(today);p.setPaymentMethod(PaymentMethod.CASH);p.setReceiptNumber(UUID.randomUUID().toString());p.setIdempotencyKey(UUID.randomUUID().toString());p.setRequestHash("test");p.setRecordedBy(adminUser);p.setStatus(status);p.setRemarks("INTERNAL PAYMENT NOTE");return persist(p);}
 @Test void feesExcludeVoidsAndReceiptsCheckBothStudentAndLink()throws Exception{verified();var f=feeAccount(student);var i=new FeeInstallment();i.setFeeAccount(f);i.setInstallmentNumber(1);i.setAmount(new BigDecimal("1000.00"));i.setDueDate(today.minusDays(1));persist(i);var p=payment(f,FeePaymentStatus.SUCCESS);var voided=payment(f,FeePaymentStatus.VOIDED);for(var row:List.of(p,voided)){var allocation=new PaymentAllocation();allocation.setPayment(row);allocation.setInstallment(i);allocation.setAmount(row.getAmount());persist(allocation);}var response=mvc.perform(get(childPath("/fees")).header("Authorization","Bearer "+parent)).andExpect(status().isOk()).andExpect(jsonPath("totals.totalPaid").value(200)).andExpect(jsonPath("totals.outstanding").value(800)).andExpect(jsonPath("totals.overdue").value(800)).andReturn();assertThat(response.getResponse().getContentAsString()).doesNotContain("INTERNAL PAYMENT NOTE","requestHash");mvc.perform(get(childPath("/payments/"+p.getId()+"/receipt")).header("Authorization","Bearer "+parent)).andExpect(status().isOk()).andExpect(content().contentType("application/pdf"));var otherPayment=payment(feeAccount(other),FeePaymentStatus.SUCCESS);mvc.perform(get(childPath("/payments/"+otherPayment.getId()+"/receipt")).header("Authorization","Bearer "+parent)).andExpect(status().isForbidden());mvc.perform(get(childPath("/payments/"+p.getId()+"/receipt")).header("Authorization","Bearer "+parent2)).andExpect(status().isForbidden());}
 ExamResult result(boolean published){var e=new Exam();e.setExamCode(UUID.randomUUID().toString());e.setTitle(published?"Published exam":"Hidden exam");e.setBatch(batch);e.setExamType(ExamType.OFFLINE);e.setTotalMarks(new BigDecimal("80"));e.setPassingMarks(new BigDecimal("40"));e.setStartDateTime(now.minusSeconds(172800));e.setEndDateTime(now.minusSeconds(169200));e.setEligibilityDate(today.minusDays(2));e.setCreatedBy(adminUser);e.setStatus(published?ExamStatus.COMPLETED:ExamStatus.PUBLISHED);e.setResultsPublished(published);if(published){e.setResultsPublishedAt(now);e.setResultsPublishedBy(adminUser);}persist(e);var r=new ExamResult();r.setExam(e);r.setStudent(student);r.setObtainedMarks(new BigDecimal("64"));r.setEvaluatedAt(now);r.setEvaluatedBy(adminUser);r.setRemarks("INTERNAL EXAM NOTE");return persist(r);}
 @Test void onlyPublishedEligibleResultsAndSharedGradesAreVisible()throws Exception{verified();result(false);result(true);var r=mvc.perform(get(childPath("/results")).header("Authorization","Bearer "+parent)).andExpect(status().isOk()).andExpect(jsonPath("totalElements").value(1)).andExpect(jsonPath("content[0].percentage").value(80)).andExpect(jsonPath("content[0].grade").value("A")).andExpect(jsonPath("content[0].passed").value(true)).andReturn();assertThat(r.getResponse().getContentAsString()).doesNotContain("Hidden exam","correctOption","INTERNAL EXAM NOTE");mvc.perform(get(childPath("/progress")).header("Authorization","Bearer "+parent)).andExpect(status().isOk()).andExpect(jsonPath("averageExamPercentage").value(80));}
 Assignment assignment(AssignmentStatus status,boolean recipient){var x=new Assignment();x.setTitle(status+" homework");x.setBatch(batch);x.setCreatedBy(adminUser);x.setMaxMarks(new BigDecimal("100"));x.setDueDateTime(now.plusSeconds(1800));x.setStatus(status);if(status!=AssignmentStatus.DRAFT)x.setPublishedAt(now.minusSeconds(100));persist(x);if(recipient){var r=new AssignmentRecipient();r.setAssignment(x);r.setStudent(student);persist(r);}return x;}
 @Test void assignmentSnapshotAndGradedFeedbackAreRespected()throws Exception{verified();assignment(AssignmentStatus.DRAFT,true);assignment(AssignmentStatus.PUBLISHED,false);assignment(AssignmentStatus.PUBLISHED,true);var x=assignment(AssignmentStatus.CLOSED,true);var s=new AssignmentSubmission();s.setAssignment(x);s.setStudent(student);s.setSubmittedAt(now.minusSeconds(50));s.setStatus(SubmissionStatus.GRADED);s.setObtainedMarks(new BigDecimal("85"));s.setFeedback("Good work");s.setGradedBy(adminUser);s.setGradedAt(now);persist(s);mvc.perform(get(childPath("/assignments")).header("Authorization","Bearer "+parent)).andExpect(status().isOk()).andExpect(jsonPath("totalElements").value(2));mvc.perform(get(childPath("/assignments")).param("status","GRADED").header("Authorization","Bearer "+parent)).andExpect(jsonPath("content[0].feedback").value("Good work")).andExpect(jsonPath("content[0].obtainedMarks").value(85));mvc.perform(get(childPath("/progress")).header("Authorization","Bearer "+parent)).andExpect(jsonPath("eligibleAssignments").value(2)).andExpect(jsonPath("assignmentCompletionPercentage").value(50));}
 @Test void resourceMetadataFollowsCurrentEnrollmentWithoutDownloadBypass()throws Exception{verified();var c=new ResourceCategory();c.setName("Notes");c.setNormalizedName("notes");persist(c);for(var visibility:ResourceVisibility.values()){var m=new StudyMaterial();m.setTitle(visibility+" notes");m.setCourse(course);m.setCategory(c);m.setResourceType(ResourceType.LINK);m.setExternalUrl("https://example.org");m.setVisibility(visibility);m.setUploadedBy(adminUser);m.setPublishedAt(now);persist(m);}mvc.perform(get(childPath("/resources")).header("Authorization","Bearer "+parent)).andExpect(status().isOk()).andExpect(jsonPath("totalElements").value(1)).andExpect(jsonPath("content[0].title").value("PUBLISHED notes"));mvc.perform(get("/api/resources/materials").header("Authorization","Bearer "+parent)).andExpect(status().isForbidden());enrollment.setStatus(EnrollmentStatus.WITHDRAWN);enrollment.setWithdrawalDate(today);em.flush();mvc.perform(get(childPath("/resources")).header("Authorization","Bearer "+parent)).andExpect(jsonPath("totalElements").value(0));}
 @Test void parentCannotWriteAnyAcademicOrFinancialData()throws Exception{verified();for(String url:List.of("/api/attendance/sessions","/api/fees/accounts","/api/exams","/api/assignments","/api/parents/links"))mvc.perform(json(post(url),Map.of(),parent)).andExpect(status().is4xxClientError());var x=assignment(AssignmentStatus.PUBLISHED,true);mvc.perform(json(post("/api/assignments/"+x.getId()+"/submissions"),Map.of("submissionText","Parent work"),parent)).andExpect(status().isForbidden());}
 @Test void invalidRangesAndUnauthenticatedRequestsAreRejected()throws Exception{verified();mvc.perform(get(childPath("/progress")).param("fromDate",today.toString()).param("toDate",today.minusDays(1).toString()).header("Authorization","Bearer "+parent)).andExpect(status().isBadRequest());mvc.perform(get("/api/parents/me/children")).andExpect(status().isUnauthorized());}
 @Test void nameOnlyUpdatesAdvanceProfileVersion()throws Exception{var p=body(mvc.perform(json(put("/api/parents/me"),Map.of("version",0,"fullName","Changed Name","phoneNumber","9876543210"),parent)).andExpect(status().isOk()).andReturn());assertThat(p.get("version").asLong()).isGreaterThan(0);mvc.perform(json(put("/api/parents/me"),Map.of("version",0,"fullName","Stale Name","phoneNumber","9876543210"),parent)).andExpect(status().isConflict());}
 @Test void validWritePayloadsAreStillForbiddenToParents()throws Exception{verified();mvc.perform(json(post("/api/attendance/sessions"),Map.of("batchId",batch.getId(),"sessionDate",today.toString(),"startTime","09:00","endTime","10:00"),parent)).andExpect(status().isForbidden());mvc.perform(json(post("/api/fees/accounts"),Map.of("enrollmentId",enrollment.getId(),"feeStructureId",1,"discountAmount",0,"agreementDate",today.toString()),parent)).andExpect(status().isForbidden());mvc.perform(json(put("/api/exams/1/offline-results"),Map.of("version",0,"results",List.of(Map.of("studentId",student.getId(),"obtainedMarks",1))),parent)).andExpect(status().isForbidden());}
}
